Given a 2d matrix of strings arr[][] of order n * 2, where each array arr[i] contains two strings, where the first string arr[i][0] is the employee and arr[i][1] is his manager. The task is to find the count of the number of employees under each manager in the hierarchy and not just their direct reports.Note: Every employee reports to only one manager. And the CEO reports to himself. Print the result in sorted order based on employee name.Example:Input: arr[][] = [[A, C], [B, C], [C, F], [D, E], [E, F], [F, F]]Output: [[A, 0], [B, 0], [C, 2], [D, 0], [E, 1], [F, 5]]Explanation: 'A' and 'B' are reporting to 'C', thus for 'C' the count is 2. And 'D' is reporting to 'E', thus for 'E' the count is 1. 'C' and 'E' reporting to 'F' . Thus count for 'F' is 5 ( 2 under 'C'+ 1 under 'E' + 'C' + 'E' )  . And no employees are reporting 'A', 'B', and 'D', so the count for them is 0.Approach:The idea is to store all the employees working under the manager in a HashMap, and then find the count of employees under each manager, and at last sum them all to find the count of direct and indirect employees working under any manager. To do so, first create a HashMap to store the employees under every manager. Also, create a HashMap to store the results. Now start traversal from any of the employee, and perform DFS to find the count of all the employees. Find the sum of all the direct and indirect employees and store the sum in results. At last, store the results in an array in the pairs of employee and the count of employees working under him.
            C++

    // C++ program to find number of
// employees under every manager
#include <bits/stdc++.h>
using namespace std;

// Helper function to recursively count 
// the number of employees under a manager
int findEmployees(unordered_map<string, vector<string>> &dataset, 
            unordered_map<string, int> &result, string mngr) {

    // if the result is already calculated
    if(result[mngr] != -1) {
        return result[mngr];
    }

    // if the manager is not present in the dataset
    if(dataset.find(mngr) == dataset.end()) {
        result[mngr] = 0;
        return 0;
    }

    // count the number of employees under the manager
    int count = 0;
    for(auto i:dataset[mngr]) {

        if(result[i]!=-1)
        count+= result[i];

        else {
        result[i]= findEmployees(dataset, result, i);
        count+= result[i];
        }
    }
    result[mngr] = count + dataset[mngr].size();
    return result[mngr];
}

// Function to find the count of 
// employees under each manager
vector<pair<string, int>> findCount(vector<vector<string>> arr) {

    // to store the employees under each manager
    unordered_map<string, vector<string>> dataset;

    // to store the results 
    unordered_map<string, int> result;
    for(auto i:arr) {
        if(i[1] == i[0]) continue;
        dataset[i[1]].push_back(i[0]);

        // initialize the result with -1
        result[i[0]] = -1;
        result[i[1]] = -1;
    }

    for(auto i: result) {

        // if the manager is not visited yet
        if(i.second == -1) {
            findEmployees(dataset, result, i.first);
        }
    }

    vector<pair<string, int>> res;
    for(auto i:result) {
        res.push_back({i.first, i.second});
    }

    return res;
}

int main() {
    vector<vector<string>> arr = {
        {"A", "C"},
        {"B", "C"},
        {"C", "F"},
        {"D", "E"},
        {"E", "F"},
        {"F", "F"}
    };

    vector<pair<string, int>> result = findCount(arr);

    // sort the result
    sort(result.begin(), result.end());
    for(auto i:result) {
        cout << i.first << ": " << i.second << endl;
    }
    return 0;
}


